window.__PIONEER_REGISTER_TEST("TEST_HIST_SET_39", [
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. वारेन हेस्टिंग्स के काल में ही 1784 में सर विलियम जोन्स ने 'एशियाटिक सोसाइटी ऑफ बंगाल' स्थापित की तथा चार्ल्स विल्किंस ने भगवद्गीता का प्रथम अंग्रेजी अनुवाद किया।\n2. लॉर्ड हार्डिंग द्वितीय के समय दिसंबर 1911 में सम्राट जॉर्ज पंचम के स्वागत में दिल्ली दरबार लगा जहाँ बंगाल विभाजन रद्द करने व राजधानी कलकत्ता से दिल्ली (1912 में स्थानांतरित) करने की घोषणा हुई।\n3. प्रमुख संधियाँ एवं समझौते के अंतर्गत 'पूना समझौता / पूना पैक्ट (1932 ई.)' का ऐतिहासिक संबंध 'प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी' से था।\n4. फ्लोरेंस नाइटिंगेल ने लॉर्ड रिपन को 'भारत का उद्धारक' कहा था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: 'पूना समझौता / पूना पैक्ट (1932 ई.)' का सही संबंध 'दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)' से था — मदन मोहन मालवीय व राजेंद्र प्रसाद के प्रयासों से गांधीजी की ओर से हस्ताक्षर व डॉ. आंबेडकर के बीच पूना पैक्ट हुआ।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)   B. भारत शासन अधिनियम, 1935\nC. विजयी विश्व तिरंगा प्यारा   D. 1916 लखनऊ अधिवेशन\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["अधिवेशन","1916 लखनऊ अधिवेशन","भारत शासन अधिनियम, 1935","विजयी विश्व तिरंगा प्यारा"],"correct":0,"explanation":"1916 लखनऊ अधिवेशन (1916 ई.), विजयी विश्व तिरंगा प्यारा (1924 ई.), भारत शासन अधिनियम, 1935 (1935 ई.), 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) (1946 ई.)। अतः सबसे अंत में 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1946 के कैबिनेट मिशन के तीन सदस्यों में सर जॉन साइमन, लॉर्ड माउंटबेटन और क्लीमेंट एटली शामिल थे जिन्होंने दो स्वतंत्र राज्यों की सिफारिश की।\nकथन-2: चटगाँव शस्त्रागार छापे (अप्रैल 1930) का नेतृत्व रामप्रसाद बिस्मिल और अशफाकुल्ला खाँ ने हिंदुस्तान रिपब्लिकन एसोसिएशन के तहत किया था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) कैबिनेट मिशन (1946) के तीन सदस्य लॉर्ड पैथिक लॉरेंस (भारत सचिव व अध्यक्ष), सर स्टैफोर्ड क्रिप्स और ए.वी. अलेक्जेंडर थे; इसने पाकिस्तान की माँग अस्वीकार की थी। (2) चटगाँव शस्त्रागार छापा (1930) 'मास्टर दा' सूर्य सेन की इंडियन रिपब्लिकन आर्मी (IRA) द्वारा किया गया जिसमें प्रीतिलता वादेदार, कल्पना दत्त, शांति घोष व सुनीति चौधरी जैसी वीरांगनाएँ थीं।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. प्रमुख आयोग एवं उद्देश्य के अंतर्गत 'ह्विटले आयोग (Whitley, 1929)' का ऐतिहासिक संबंध 'ब्रिटिश क्राउन व भारतीय देसी रियासतों के मध्य संबंध' से था।\n2. कांग्रेस अधिवेशन एवं अध्यक्ष के अंतर्गत '1937 फैजपुर अधिवेशन (प्रथम ग्रामीण सत्र)' का ऐतिहासिक संबंध 'मौलाना अबुल कलाम आजाद' से था।\n3. कांग्रेस अधिवेशन एवं अध्यक्ष के अंतर्गत '1929 लाहौर अधिवेशन' का ऐतिहासिक संबंध 'सरदार वल्लभभाई पटेल' से था।\n4. तेज बहादुर सप्रू व एम.आर. जयकर के प्रयासों से 5 मार्च 1931 को गांधी-इरविन समझौता हुआ।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (तेज बहादुर सप्रू व एम.आर. जयकर के प्रयासों से 5 मार्च 1931 को गांधी-इरविन समझौता हुआ।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. क्रांतिकारी आंदोलन प्रथम चरण: महाराष्ट्र, बंगाल व विदेश में क्रांति   B. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)\nC. कांग्रेस-पूर्व राजनीतिक संगठन (1836–1885)   D. द्वितीय क्रांतिकारी चरण: HRA, काकोरी, HSRA, भगत सिंह व सूर्य सेन\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["कांग्रेस-पूर्व राजनीतिक संगठन (1836–1885)","द्वितीय क्रांतिकारी चरण: HRA, काकोरी, HSRA, भगत सिंह व सूर्य सेन","(समय )","क्रांतिकारी आंदोलन प्रथम चरण: महाराष्ट्र, बंगाल व विदेश में क्रांति"],"correct":2,"explanation":"कांग्रेस-पूर्व राजनीतिक संगठन (1836–1885) (1876 ई.), क्रांतिकारी आंदोलन प्रथम चरण: महाराष्ट्र, बंगाल व विदेश में क्रांति (1913 ई.), द्वितीय क्रांतिकारी चरण: HRA, काकोरी, HSRA, भगत सिंह व सूर्य सेन (1928 ई.), 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) (1946 ई.)। अतः सबसे अंत में 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. आजाद हिंद फौज (INA) की पहली सैन्य स्थापना 1943 में बर्लिन में रासबिहारी बोस की बजाय सरदार भगत सिंह के नेतृत्व में हुई थी।\n2. 1887 मद्रास अधिवेशन में बदरुद्दीन तैयबजी ने कांग्रेस के धर्मनिरपेक्ष स्वरूप को सुदृढ़ किया।\n3. भारत छोड़ो आंदोलन को 'अगस्त क्रांति' भी कहा जाता है; भारतीय कम्युनिस्ट पार्टी (सोवियत संघ पर जर्मन हमले के बाद 'जनयुद्ध' नीति से), हिंदू महासभा व मुस्लिम लीग ने इसमें भाग नहीं लिया।\n4. स्कॉटिश व्यापारी जॉर्ज यूल ने 1888 में इलाहाबाद अधिवेशन की अध्यक्षता की।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: आजाद हिंद फौज (INA) की प्रथम स्थापना का विचार व गठन 1942 में दक्षिण-पूर्व एशिया (मलय) में कैप्टन मोहन सिंह व जापानी मेजर फुजिवारा की सहायता से हुआ, जिसे 1943 में रासबिहारी बोस ने सुभाष को सौंपा।"},
  {"q":"[PSC/CDS युग्म पहचान — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) : आचार्य जे.बी. कृपलानी\n2. 1924 बेलगाम अधिवेशन : मौलाना अबुल कलाम आजाद\n3. 1940 रामगढ़ अधिवेशन : सरोजिनी नायडू (प्रथम भारतीय महिला)\n4. 1925 कानपुर अधिवेशन : अंबिका चरण मजूमदार","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: 15 अगस्त 1947 को जब भारत स्वतंत्र हुआ तब कांग्रेस के अध्यक्ष आचार्य जे.बी. कृपलानी थे। (अन्य सही युग्म: 1924 बेलगाम अधिवेशन→महात्मा गांधी, 1940 रामगढ़ अधिवेशन→मौलाना अबुल कलाम आजाद, 1925 कानपुर अधिवेशन→सरोजिनी नायडू (प्रथम भारतीय महिला))।"},
  {"q":"1942 के भारत छोड़ो आंदोलन के दौरान 'करो या मरो' (Do or Die) का नारा किसने दिया?","options":["बाल गंगाधर तिलक","लाला लाजपत राय","महात्मा गांधी","सुभाष चंद्र बोस"],"correct":2,"explanation":"8 अगस्त 1942 को बंबई के ग्वालिया टैंक मैदान में गांधीजी ने अंतिम अहिंसक संग्राम हेतु 'करो या मरो' मंत्र दिया। यूसुफ मेहरअली ने 'भारत छोड़ो' तथा 'साइमन वापस जाओ' जैसे लोकप्रिय नारे गढ़े थे।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: कांग्रेस अधिवेशन एवं अध्यक्ष के अंतर्गत '1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)' का ऐतिहासिक संबंध 'व्योमेश चंद्र बनर्जी' से था।\nकथन-2: रावी तट पर लाहौर में जवाहरलाल नेहरू की अध्यक्षता में 31 दिसंबर 1929 को तिरंगा फहराकर पूर्ण स्वराज घोषित हुआ।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)' का सही संबंध 'आचार्य जे.बी. कृपलानी' से था — 15 अगस्त 1947 को जब भारत स्वतंत्र हुआ तब कांग्रेस के अध्यक्ष आचार्य जे.बी. कृपलानी थे।)। कथन-2 सत्य है (रावी तट पर लाहौर में जवाहरलाल नेहरू की अध्यक्षता में 31 दिसंबर 1929 को तिरंगा फहराकर पूर्ण स्वराज घोषित हुआ।)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: प्रमुख संधियाँ एवं समझौते के अंतर्गत 'गांधी-इरविन समझौता (1931 ई.)' का ऐतिहासिक संबंध 'दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)' से था।\nकथन-2: संवैधानिक अधिनियम एवं प्रावधान के अंतर्गत 'भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड)' का ऐतिहासिक संबंध 'अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'गांधी-इरविन समझौता (1931 ई.)' का सही संबंध 'सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी' से था — तेज बहादुर सप्रू व एम.आर. जयकर के प्रयासों से 5 मार्च 1931 को गांधी-इरविन समझौता हुआ। (2) 'भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड)' का सही संबंध 'प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली' से था — 1919 के भारत शासन अधिनियम (मोंटफोर्ड सुधार) ने महिलाओं को मताधिकार व भारत हेतु उच्चायुक्त पद भी सृजित किया।"},
  {"q":"[UPSC Prelims PYQ] 8 अगस्त 1942 के 'भारत छोड़ो प्रस्ताव' के संदर्भ में कौन-सा कथन सही है?","options":["इस आंदोलन की पूर्व संध्या पर गांधीजी ने सरकारी कर्मचारियों को त्यागपत्र न देने व भारतीय रियासतों की जनता से शासकों का साथ देने","आंदोलन के समय मुस्लिम लीग ने बंबई में कांग्रेस के साथ संयुक्त कार्यसमिति बनाई","भारतीय कम्युनिस्ट पार्टी ने भूमिगत कांग्रेस रेडियो का पूर्ण संचालन किया","इसकी घोषणा वायसराय लॉर्ड वेवेल के इस्तीफे के साथ हुई"],"correct":0,"explanation":"ग्वालिया टैंक भाषण (8 अगस्त 1942) में गांधीजी ने सरकारी कर्मियों से नौकरी न छोड़ने पर कांग्रेस के प्रति निष्ठा घोषित करने, सैनिकों से भाइयों पर गोली न चलाने और छात्रों से आत्मविश्वास होने पर ही पढ़ाई छोड़ने को कहा (UPSC CSE 2021 संदर्भ)। [यदि वे संप्रभुता मानें]"},
  {"q":"ऐतिहासिक संदर्भ में 'सी.आर. फॉर्मूला (1944); देसाई-लियाकत समझौता; वेवेल योजना/शिमला सम्मेलन (जून 1945 — मुस्लिम लीग के वीटो से विफल); कैबिनेट मिशन (मार्च 1946 — लॉर्ड पैथिक लॉरेंस अध्यक्ष, सर स्टैफोर्ड क्रिप्स, ए.वी. अलेक्जेंडर — पाकिस्तान अस्वीकार, त्रिस्तरीय प्रांतीय समूह A, B, C व संविधान सभा)' (स्वतंत्रता की ओर अंतिम चरण) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["अगस्त प्रस्ताव (1940), व्यक्तिगत सत्याग्रह एवं क्रिप्स मिशन (1942)","सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946)","योजना (), मिशन (1946) व माउंटबेटन योजना (1947)","भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो"],"correct":2,"explanation":"16 अगस्त 1946 को मुस्लिम लीग द्वारा 'प्रत्यक्ष कार्यवाही दिवस' (Direct Action Day) मनाने से भीषण सांप्रदायिक दंगे भड़के; अंततः रेडक्लिफ आयोग ने भारत-पाकिस्तान सीमा निर्धारित की।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)   B. इंकलाब जिंदाबाद\nC. वेवेल योजना (1945), कैबिनेट मिशन (1946) व माउंटबेटन योजना (1947)   D. 1887 मद्रास अधिवेशन\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["इंकलाब जिंदाबाद","(), () व ()","सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)","1887 मद्रास अधिवेशन"],"correct":1,"explanation":"1887 मद्रास अधिवेशन (1887 ई.), सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916) (1917 ई.), इंकलाब जिंदाबाद (1929 ई.), वेवेल योजना (1945), कैबिनेट मिशन (1946) व माउंटबेटन योजना (1947) (1946 ई.)। अतः सबसे अंत में वेवेल योजना (1945), कैबिनेट मिशन (1946) व माउंटबेटन योजना (1947)।"},
  {"q":"[PSC/CDS युग्म पहचान — प्रमुख संधियाँ एवं समझौते] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. सुगौली की संधि (1816 ई.) : प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)\n2. पूना समझौता / पूना पैक्ट (1932 ई.) : दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)\n3. यांडबू की संधि (1826 ई.) : प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति)\n4. सालबाई की संधि (1782 ई.) : ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: मदन मोहन मालवीय व राजेंद्र प्रसाद के प्रयासों से गांधीजी की ओर से हस्ताक्षर व डॉ. आंबेडकर के बीच पूना पैक्ट हुआ। (अन्य सही युग्म: सुगौली की संधि (1816 ई.)→आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले), यांडबू की संधि (1826 ई.)→प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त), सालबाई की संधि (1782 ई.)→प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति))।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. प्रमुख ऐतिहासिक कांग्रेस अधिवेशन (1896–1929)   B. ली आयोग (Lee Commission, 1923)\nC. पूना समझौता / पूना पैक्ट (1932 ई.)   D. भारतीय राष्ट्रीय कांग्रेस की स्थापना (1885) एवं प्रथम चार अधिवेशन\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["/ (ई.)","ली आयोग (Lee Commission, 1923)","भारतीय राष्ट्रीय कांग्रेस की स्थापना (1885) एवं प्रथम चार अधिवेशन","प्रमुख ऐतिहासिक कांग्रेस अधिवेशन (1896–1929)"],"correct":0,"explanation":"भारतीय राष्ट्रीय कांग्रेस की स्थापना (1885) एवं प्रथम चार अधिवेशन (1885 ई.), प्रमुख ऐतिहासिक कांग्रेस अधिवेशन (1896–1929) (1916 ई.), ली आयोग (Lee Commission, 1923) (1923 ई.), पूना समझौता / पूना पैक्ट (1932 ई.) (1932 ई.)। अतः सबसे अंत में पूना समझौता / पूना पैक्ट (1932 ई.)।"},
  {"q":"[UPSC Prelims पैटर्न — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. 1940 रामगढ़ अधिवेशन : जॉर्ज यूल (प्रथम अंग्रेज अध्यक्ष)\n2. 1888 इलाहाबाद अधिवेशन : सरदार वल्लभभाई पटेल\n3. 1931 कराची अधिवेशन : डॉ. रासबिहारी घोष\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: 1940 रामगढ़ अधिवेशन — मौलाना अबुल कलाम आजाद)। युग्म 2 गलत (सही: 1888 इलाहाबाद अधिवेशन — जॉर्ज यूल (प्रथम अंग्रेज अध्यक्ष))। युग्म 3 गलत (सही: 1931 कराची अधिवेशन — सरदार वल्लभभाई पटेल)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: भारत छोड़ो आंदोलन को 'अगस्त क्रांति' भी कहा जाता है; भारतीय कम्युनिस्ट पार्टी (सोवियत संघ पर जर्मन हमले के बाद 'जनयुद्ध' नीति से), हिंदू महासभा व मुस्लिम लीग ने इसमें भाग नहीं लिया।\nकथन-2: 28 दिसंबर 1885 को बंबई में हुए पहले कांग्रेस अधिवेशन की अध्यक्षता डब्ल्यू.सी. बनर्जी ने की।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) भारत छोड़ो आंदोलन को 'अगस्त क्रांति' भी कहा जाता है; भारतीय कम्युनिस्ट पार्टी (सोवियत संघ पर जर्मन हमले के बाद 'जनयुद्ध' नीति से), हिंदू महासभा व मुस्लिम लीग ने इसमें भाग नहीं लिया। (2) 28 दिसंबर 1885 को बंबई में हुए पहले कांग्रेस अधिवेशन की अध्यक्षता डब्ल्यू.सी. बनर्जी ने की।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. क्रांतिकारी घटनाएँ एवं नायक के अंतर्गत 'काकोरी कांड (9 अगस्त 1925)' का ऐतिहासिक संबंध 'भगत सिंह एवं बटुकेश्वर दत्त' से था।\n2. 1938 के हरिपुरा कांग्रेस अधिवेशन में 'राष्ट्रीय योजना समिति' का गठन बाल गंगाधर तिलक की अध्यक्षता में किया गया था।\n3. ऐतिहासिक नारे एवं उद्घोष के अंतर्गत 'सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत)' का ऐतिहासिक संबंध 'बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)' से था।\n4. 1940 के रामगढ़ अधिवेशन में मौलाना आजाद अध्यक्ष बने और विश्व युद्ध संकट के कारण 1940-46 तक लगातार अध्यक्ष रहे।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (1940 के रामगढ़ अधिवेशन में मौलाना आजाद अध्यक्ष बने और विश्व युद्ध संकट के कारण 1940-46 तक लगातार अध्यक्ष रहे।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. कर्जन वायली वध (लंदन, 1909)   B. 1916 लखनऊ अधिवेशन\nC. अगस्त प्रस्ताव (1940), व्यक्तिगत सत्याग्रह एवं क्रिप्स मिशन (1942)   D. वेवेल योजना (1945), कैबिनेट मिशन (1946) व माउंटबेटन योजना (1947)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["(), मिशन () व ()","कर्जन वायली वध (लंदन, 1909)","अगस्त प्रस्ताव (1940), व्यक्तिगत सत्याग्रह एवं क्रिप्स मिशन (1942)","1916 लखनऊ अधिवेशन"],"correct":0,"explanation":"कर्जन वायली वध (लंदन, 1909) (1909 ई.), 1916 लखनऊ अधिवेशन (1916 ई.), अगस्त प्रस्ताव (1940), व्यक्तिगत सत्याग्रह एवं क्रिप्स मिशन (1942) (1940 ई.), वेवेल योजना (1945), कैबिनेट मिशन (1946) व माउंटबेटन योजना (1947) (1946 ई.)। अतः सबसे अंत में वेवेल योजना (1945), कैबिनेट मिशन (1946) व माउंटबेटन योजना (1947)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो   B. बंगाल गवर्नर पर गोली (1932)\nC. सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)   D. 1931 कराची अधिवेशन\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)","बंगाल गवर्नर पर गोली (1932)","भारत (), व","1931 कराची अधिवेशन"],"correct":2,"explanation":"सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916) (1917 ई.), 1931 कराची अधिवेशन (1931 ई.), बंगाल गवर्नर पर गोली (1932) (1932 ई.), भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो (1942 ई.)। अतः सबसे अंत में भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो।"},
  {"q":"ऐतिहासिक संदर्भ में 'मलय में कैप्टन मोहन सिंह व रासबिहारी बोस (इंडियन इंडिपेंडेंस लीग 1942) द्वारा INA विचार; अक्टूबर 1943 सिंगापुर में सुभाष चंद्र बोस द्वारा 'आजाद हिंद सरकार' व कमान संभालना ('तुम मुझे खून दो...', 'दिल्ली चलो'); ब्रिगेड: सुभाष, गांधी, नेहरू, आजाद व 'रानी झांसी रेजिमेंट' (लक्ष्मी सहगल); अंडमान-निकोबार (शहीद व स्वराज द्वीप)' (INA गठन व अभियान) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो","बोस, फौज (INA) एवं नौसेना विद्रोह (1946)","अगस्त प्रस्ताव (1940), व्यक्तिगत सत्याग्रह एवं क्रिप्स मिशन (1942)","वेवेल योजना (1945), कैबिनेट मिशन (1946) व माउंटबेटन योजना (1947)"],"correct":1,"explanation":"नवंबर 1945 के INA लाल किला मुकदमों व फरवरी 1946 के शाही भारतीय नौसेना (RIN) विद्रोह (जिसमें सरदार पटेल व जिन्ना के समझाने पर आत्मसमर्पण हुआ) ने ब्रिटिश साम्राज्य की सैन्य निष्ठा तोड़ दी।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. 1907 सूरत अधिवेशन   B. राजगोपालाचारी फार्मूला (1944), देसाई-लियाकत व वेवेल शिमला सम्मेलन\nC. भारतीय परिषद अधिनियम, 1909   D. सरफरोशी की तमन्ना...\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["1907 सूरत अधिवेशन","भारतीय परिषद अधिनियम, 1909","सरफरोशी की तमन्ना...","फार्मूला"],"correct":3,"explanation":"1907 सूरत अधिवेशन (1907 ई.), भारतीय परिषद अधिनियम, 1909 (1909 ई.), सरफरोशी की तमन्ना... (1927 ई.), राजगोपालाचारी फार्मूला (1944), देसाई-लियाकत व वेवेल शिमला सम्मेलन (1945 ई.)। अतः सबसे अंत में राजगोपालाचारी फार्मूला (1944), देसाई-लियाकत व वेवेल शिमला सम्मेलन।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. ऐतिहासिक नारे एवं उद्घोष के अंतर्गत 'स्वराज मेरा जन्मसिद्ध अधिकार है' का ऐतिहासिक संबंध 'लाला लाजपत राय' से था।\n2. 8 अगस्त 1942 को बंबई के ग्वालिया टैंक मैदान में गांधीजी ने अंतिम अहिंसक संग्राम हेतु 'करो या मरो' मंत्र दिया।\n3. कांग्रेस अधिवेशन एवं अध्यक्ष के अंतर्गत '1887 मद्रास अधिवेशन' का ऐतिहासिक संबंध 'जॉर्ज यूल (प्रथम अंग्रेज अध्यक्ष)' से था।\n4. 1942 के भारत छोड़ो आंदोलन के दौरान सबसे अल्पकालिक समानांतर सरकार सतारा में केवल एक सप्ताह चली जबकि सबसे दीर्घकालिक बलिया में तीन वर्षों तक चली।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (8 अगस्त 1942 को बंबई के ग्वालिया टैंक मैदान में गांधीजी ने अंतिम अहिंसक संग्राम हेतु 'करो या मरो' मंत्र दिया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"ऐतिहासिक संदर्भ में '8 अगस्त 1942 ग्वालिया टैंक (बंबई) बैठक — 'करो या मरो' मंत्र (प्रस्ताव नेहरू ने, समर्थन पटेल ने); 9 अगस्त 'ऑपरेशन जीरो ऑवर' से सभी बड़े नेता गिरफ्तार; भूमिगत नेता: जयप्रकाश नारायण (हजारीबाग जेल से भागे, 'आजाद दस्ता'), राममनोहर लोहिया, अरुणा आसफ अली (झंडा फहराया), अच्युत पटवर्धन, उषा मेहता (कांग्रेस रेडियो)' (आंदोलन एवं केंद्र) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["भारत छोड़ो (1942), समानांतर सरकारें व","वेवेल योजना (1945), कैबिनेट मिशन (1946) व माउंटबेटन योजना (1947)","सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946)","अगस्त प्रस्ताव (1940), व्यक्तिगत सत्याग्रह एवं क्रिप्स मिशन (1942)"],"correct":0,"explanation":"बंबई से गुप्त 'कांग्रेस रेडियो' का संचालन करने वाली उषा मेहता को राममनोहर लोहिया का सहयोग मिला था; महात्मा गांधी आगा खाँ पैलेस में व नेहरू-आजाद अहमदनगर किले में कैद रखे गए।"},
  {"q":"[UPSC Prelims पैटर्न — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. 1940 रामगढ़ अधिवेशन : सरोजिनी नायडू (प्रथम भारतीय महिला)\n2. 1925 कानपुर अधिवेशन : आचार्य जे.बी. कृपलानी\n3. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) : जॉर्ज यूल (प्रथम अंग्रेज अध्यक्ष)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: 1940 रामगढ़ अधिवेशन — मौलाना अबुल कलाम आजाद)। युग्म 2 गलत (सही: 1925 कानपुर अधिवेशन — सरोजिनी नायडू (प्रथम भारतीय महिला))। युग्म 3 गलत (सही: 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) — आचार्य जे.बी. कृपलानी)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. 1888 इलाहाबाद अधिवेशन   B. सरफरोशी की तमन्ना...\nC. द्वितीय क्रांतिकारी चरण: HRA, काकोरी, HSRA, भगत सिंह व सूर्य सेन   D. 1940 रामगढ़ अधिवेशन\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["सरफरोशी की तमन्ना...","1888 इलाहाबाद अधिवेशन","अधिवेशन","द्वितीय क्रांतिकारी चरण: HRA, काकोरी, HSRA, भगत सिंह व सूर्य सेन"],"correct":2,"explanation":"1888 इलाहाबाद अधिवेशन (1888 ई.), सरफरोशी की तमन्ना... (1927 ई.), द्वितीय क्रांतिकारी चरण: HRA, काकोरी, HSRA, भगत सिंह व सूर्य सेन (1928 ई.), 1940 रामगढ़ अधिवेशन (1940 ई.)। अतः सबसे अंत में 1940 रामगढ़ अधिवेशन।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा   B. सरफरोशी की तमन्ना...\nC. भारतीय परिषद अधिनियम, 1861   D. लॉर्ड कैनिंग, मेयो, लिटन, रिपन एवं लॉर्ड कर्जन\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["तुम खून दो, मैं","भारतीय परिषद अधिनियम, 1861","लॉर्ड कैनिंग, मेयो, लिटन, रिपन एवं लॉर्ड कर्जन","सरफरोशी की तमन्ना..."],"correct":0,"explanation":"भारतीय परिषद अधिनियम, 1861 (1861 ई.), लॉर्ड कैनिंग, मेयो, लिटन, रिपन एवं लॉर्ड कर्जन (1882 ई.), सरफरोशी की तमन्ना... (1927 ई.), तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा (1944 ई.)। अतः सबसे अंत में तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: कांग्रेस अधिवेशन एवं अध्यक्ष के अंतर्गत '1940 रामगढ़ अधिवेशन' का ऐतिहासिक संबंध 'आचार्य जे.बी. कृपलानी' से था।\nकथन-2: क्रांतिकारी घटनाएँ एवं नायक के अंतर्गत 'माइकल ओ डायर वध (1940)' का ऐतिहासिक संबंध 'खुदीराम बोस एवं प्रफुल्ल चाकी' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) '1940 रामगढ़ अधिवेशन' का सही संबंध 'मौलाना अबुल कलाम आजाद' से था — 1940 के रामगढ़ अधिवेशन में मौलाना आजाद अध्यक्ष बने और विश्व युद्ध संकट के कारण 1940-46 तक लगातार अध्यक्ष रहे। (2) 'माइकल ओ डायर वध (1940)' का सही संबंध 'सरदार उधम सिंह' से था — जलियाँवाला बाग हत्याकांड (1919) का बदला लेने के लिए 21 वर्ष बाद उधम सिंह ने लंदन में डायर को मारा।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. गांधी-इरविन समझौता (1931), गोलमेज सम्मेलन व पूना पैक्ट (1932)   B. भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो\nC. फ्रेजर आयोग (1902)   D. सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["गांधी-इरविन समझौता (1931), गोलमेज सम्मेलन व पूना पैक्ट (1932)","फ्रेजर आयोग (1902)","बोस, फौज (INA) एवं ()","भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो"],"correct":2,"explanation":"फ्रेजर आयोग (1902) (1902 ई.), गांधी-इरविन समझौता (1931), गोलमेज सम्मेलन व पूना पैक्ट (1932) (1932 ई.), भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो (1942 ई.), सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946) (1943 ई.)। अतः सबसे अंत में सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 8 अगस्त 1942 को बंबई के ग्वालिया टैंक मैदान में गांधीजी ने अंतिम अहिंसक संग्राम हेतु 'करो या मरो' मंत्र दिया।\nकथन-2: प्रमुख आयोग एवं उद्देश्य के अंतर्गत 'ह्विटली आयोग (1929 ई.)' का ऐतिहासिक संबंध 'बंगाल में स्थायी बंदोबस्त (जमींदारी प्रथा) की समीक्षा व 'तेभागा' (2/3 हिस्सा किसान को) अनुशंसा' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (8 अगस्त 1942 को बंबई के ग्वालिया टैंक मैदान में गांधीजी ने अंतिम अहिंसक संग्राम हेतु 'करो या मरो' मंत्र दिया।)। कथन-2 गलत है — 'ह्विटली आयोग (1929 ई.)' का सही संबंध 'भारतीय औद्योगिक श्रम (मजदूरों) की कार्यदशा व कल्याण स्थिति की जांच' से था — रॉयल कमीशन ऑन लेबर (ह्विटली आयोग) ने कारखानों व बागानों में श्रमिक दशा सुधार की रिपोर्ट 1931 में दी।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. गवर्नर-जनरल / वायसराय एवं कार्य के अंतर्गत 'लॉर्ड कर्जन (1899-1905)' का ऐतिहासिक संबंध 'प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन' से था।\n2. कांग्रेस अधिवेशन एवं अध्यक्ष के अंतर्गत '1911 कलकत्ता अधिवेशन' का ऐतिहासिक संबंध 'अंबिका चरण मजूमदार' से था।\n3. संवैधानिक अधिनियम एवं प्रावधान के अंतर्गत 'भारतीय परिषद अधिनियम, 1909' का ऐतिहासिक संबंध 'प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली' से था।\n4. 1946 के कैबिनेट मिशन ने मुस्लिम लीग की पूर्ण संप्रभु पाकिस्तान की माँग को व्यावहारिक न मानते हुए खारिज किया तथा प्रांतों के तीन समूहों (A-हिंदू बहुल, B-पश्चिमोत्तर, C-बंगाल/असम) सहित एक संघ व संविधान सभा का प्रस्ताव दिया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (1946 के कैबिनेट मिशन ने मुस्लिम लीग की पूर्ण संप्रभु पाकिस्तान की माँग को व्यावहारिक न मानते हुए खारिज किया तथा प्रांतों के तीन समूहों (A-हिंदू बहुल, B-पश्चिमोत्तर, C-बंगाल/असम) सहित एक संघ व संविधान सभा का प्रस्ताव दिया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS युग्म पहचान — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. 1916 लखनऊ अधिवेशन : सरदार वल्लभभाई पटेल\n2. 1931 कराची अधिवेशन : रहीमतुल्ला एम. सयानी\n3. 1896 कलकत्ता अधिवेशन : व्योमेश चंद्र बनर्जी\n4. 1940 रामगढ़ अधिवेशन : मौलाना अबुल कलाम आजाद","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: 1940 के रामगढ़ अधिवेशन में मौलाना आजाद अध्यक्ष बने और विश्व युद्ध संकट के कारण 1940-46 तक लगातार अध्यक्ष रहे। (अन्य सही युग्म: 1916 लखनऊ अधिवेशन→अंबिका चरण मजूमदार, 1931 कराची अधिवेशन→सरदार वल्लभभाई पटेल, 1896 कलकत्ता अधिवेशन→रहीमतुल्ला एम. सयानी)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)   B. सविनय अवज्ञा आंदोलन, दांडी मार्च (1930) व क्षेत्रीय सत्याग्रह\nC. प्रमुख ऐतिहासिक कांग्रेस अधिवेशन (1896–1929)   D. क्रांतिकारी आंदोलन प्रथम चरण: महाराष्ट्र, बंगाल व विदेश में क्रांति\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["क्रांतिकारी आंदोलन प्रथम चरण: महाराष्ट्र, बंगाल व विदेश में क्रांति","अधिवेशन (समय )","सविनय अवज्ञा आंदोलन, दांडी मार्च (1930) व क्षेत्रीय सत्याग्रह","प्रमुख ऐतिहासिक कांग्रेस अधिवेशन (1896–1929)"],"correct":1,"explanation":"क्रांतिकारी आंदोलन प्रथम चरण: महाराष्ट्र, बंगाल व विदेश में क्रांति (1913 ई.), प्रमुख ऐतिहासिक कांग्रेस अधिवेशन (1896–1929) (1916 ई.), सविनय अवज्ञा आंदोलन, दांडी मार्च (1930) व क्षेत्रीय सत्याग्रह (1930 ई.), 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) (1946 ई.)। अतः सबसे अंत में 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. सरफरोशी की तमन्ना...   B. लॉर्ड लिटन (1876-80)\nC. 1924 बेलगाम अधिवेशन   D. सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["1924 बेलगाम अधिवेशन","सरफरोशी की तमन्ना...","बोस, फौज (INA) एवं ()","लॉर्ड लिटन (1876-80)"],"correct":2,"explanation":"लॉर्ड लिटन (1876-80) (1878 ई.), 1924 बेलगाम अधिवेशन (1924 ई.), सरफरोशी की तमन्ना... (1927 ई.), सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946) (1943 ई.)। अतः सबसे अंत में सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. स्कॉटिश व्यापारी जॉर्ज यूल ने 1888 में इलाहाबाद अधिवेशन की अध्यक्षता की।\n2. भगत सिंह, राजगुरु और सुखदेव ने 1928 में फिरोजशाह कोटला में 'नौजवान भारत सभा' व HRA के समन्वय से समाजवाद को लक्ष्य घोषित करते हुए HSRA (हिंदुस्तान सोशलिस्ट रिपब्लिकन एसोसिएशन) बनाया।\n3. 1942 के भारत छोड़ो आंदोलन के दौरान सबसे अल्पकालिक समानांतर सरकार सतारा में केवल एक सप्ताह चली जबकि सबसे दीर्घकालिक बलिया में तीन वर्षों तक चली।\n4. मूलतः मौलाना हसरत मोहानी (1921) द्वारा रचित इस नारे को भगत सिंह व बटुकेश्वर दत्त ने 1929 में अमर किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: बलिया की चित्तू पांडे सरकार सबसे अल्पकालिक (~1 सप्ताह) थी, जबकि महाराष्ट्र के सतारा की 'प्रति सरकार' (वाई.बी. चव्हाण व नाना पाटिल) 1945 तक चलने वाली सबसे लंबी समानांतर सरकार थी।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा   B. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)\nC. काकोरी कांड (9 अगस्त 1925)   D. लॉर्ड कर्जन (1899-1905)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा","(समय )","लॉर्ड कर्जन (1899-1905)","काकोरी कांड (9 अगस्त 1925)"],"correct":1,"explanation":"लॉर्ड कर्जन (1899-1905) (1905 ई.), काकोरी कांड (9 अगस्त 1925) (1925 ई.), तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा (1944 ई.), 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) (1946 ई.)। अतः सबसे अंत में 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. ह्विटली आयोग (1929 ई.)   B. तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा\nC. गांधी-इरविन समझौता (1931), गोलमेज सम्मेलन व पूना पैक्ट (1932)   D. काकोरी कांड (9 अगस्त 1925)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["तुम खून दो, मैं","काकोरी कांड (9 अगस्त 1925)","गांधी-इरविन समझौता (1931), गोलमेज सम्मेलन व पूना पैक्ट (1932)","ह्विटली आयोग (1929 ई.)"],"correct":0,"explanation":"काकोरी कांड (9 अगस्त 1925) (1925 ई.), ह्विटली आयोग (1929 ई.) (1929 ई.), गांधी-इरविन समझौता (1931), गोलमेज सम्मेलन व पूना पैक्ट (1932) (1932 ई.), तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा (1944 ई.)। अतः सबसे अंत में तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1944 के राजगोपालाचारी फॉर्मूले की विशेषता थी कि गांधीजी के समर्थन से कांग्रेस ने पहली बार व्यावहारिक रूप से आत्मनिर्णय के सिद्धांत को जनमत संग्रह की शर्त के साथ संवाद में लाया।\nकथन-2: महात्मा गांधी ने 8 अगस्त 1942 को बंबई के ग्वालिया टैंक (अगस्त क्रांति मैदान) में 'करो या मरो' मंत्र दिया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) 1944 के राजगोपालाचारी फॉर्मूले की विशेषता थी कि गांधीजी के समर्थन से कांग्रेस ने पहली बार व्यावहारिक रूप से आत्मनिर्णय के सिद्धांत को जनमत संग्रह की शर्त के साथ संवाद में लाया। (2) महात्मा गांधी ने 8 अगस्त 1942 को बंबई के ग्वालिया टैंक (अगस्त क्रांति मैदान) में 'करो या मरो' मंत्र दिया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड)   B. भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो\nC. लॉर्ड लिनलिथगो (1936-44)   D. द इंडियन स्ट्रगल\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["लॉर्ड लिनलिथगो (1936-44)","भारत (), व","द इंडियन स्ट्रगल","भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड)"],"correct":1,"explanation":"भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) (1919 ई.), द इंडियन स्ट्रगल (1935 ई.), लॉर्ड लिनलिथगो (1936-44) (1940 ई.), भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो (1942 ई.)। अतः सबसे अंत में भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो।"},
  {"q":"[UPSC Prelims पैटर्न — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) : आचार्य जे.बी. कृपलानी\n2. 1885 बंबई अधिवेशन (प्रथम) : अंबिका चरण मजूमदार\n3. 1916 लखनऊ अधिवेशन : पं. जवाहरलाल नेहरू (ग्रामीण सत्र)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (15 अगस्त 1947 को जब भारत स्वतंत्र हुआ तब कांग्रेस के अध्यक्ष आचार्य जे.बी. कृपलानी थे।) युग्म 2 गलत (सही: 1885 बंबई अधिवेशन (प्रथम) — व्योमेश चंद्र बनर्जी)। युग्म 3 गलत (सही: 1916 लखनऊ अधिवेशन — अंबिका चरण मजूमदार)।"},
  {"q":"[UPSC Prelims पैटर्न — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) : आचार्य जे.बी. कृपलानी\n2. 1896 कलकत्ता अधिवेशन : रहीमतुल्ला एम. सयानी\n3. 1940 रामगढ़ अधिवेशन : डॉ. रासबिहारी घोष\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (15 अगस्त 1947 को जब भारत स्वतंत्र हुआ तब कांग्रेस के अध्यक्ष आचार्य जे.बी. कृपलानी थे।) युग्म 2 सही (1896 कलकत्ता अधिवेशन में रवींद्रनाथ टैगोर ने बंकिम चंद्र का 'वंदे मातरम' गाया; अध्यक्ष सयानी थे।) युग्म 3 गलत (सही: 1940 रामगढ़ अधिवेशन — मौलाना अबुल कलाम आजाद)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. क्रांतिकारी आंदोलन प्रथम चरण: महाराष्ट्र, बंगाल व विदेश में क्रांति   B. भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो\nC. बटलर समिति (1927 ई.)   D. लॉर्ड कर्जन (1899-1905)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["लॉर्ड कर्जन (1899-1905)","बटलर समिति (1927 ई.)","क्रांतिकारी आंदोलन प्रथम चरण: महाराष्ट्र, बंगाल व विदेश में क्रांति","भारत आंदोलन (), व"],"correct":3,"explanation":"लॉर्ड कर्जन (1899-1905) (1905 ई.), क्रांतिकारी आंदोलन प्रथम चरण: महाराष्ट्र, बंगाल व विदेश में क्रांति (1913 ई.), बटलर समिति (1927 ई.) (1927 ई.), भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो (1942 ई.)। अतः सबसे अंत में भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: आजाद हिंद फौज (INA) की पहली सैन्य स्थापना 1943 में बर्लिन में रासबिहारी बोस की बजाय सरदार भगत सिंह के नेतृत्व में हुई थी।\nकथन-2: क्रांतिकारी घटनाएँ एवं नायक के अंतर्गत 'कर्जन वायली वध (लंदन, 1909)' का ऐतिहासिक संबंध 'रासबिहारी बोस (अमीरचंद, अवध बिहारी, बसंत विश्वास)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) आजाद हिंद फौज (INA) की प्रथम स्थापना का विचार व गठन 1942 में दक्षिण-पूर्व एशिया (मलय) में कैप्टन मोहन सिंह व जापानी मेजर फुजिवारा की सहायता से हुआ, जिसे 1943 में रासबिहारी बोस ने सुभाष को सौंपा। (2) 'कर्जन वायली वध (लंदन, 1909)' का सही संबंध 'मदनलाल धींगरा' से था — इंडिया हाउस से जुड़े मदनलाल धींगरा ने 1 जुलाई 1909 को लंदन में कर्जन वायली को गोली मारी।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों पर विचार कीजिए:\n1. गांधी-इरविन समझौता (1931 ई.) : सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी\n2. पूना समझौता / पूना पैक्ट (1932 ई.) : दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)\n3. मंगलौर की संधि (1784 ई.) : द्वितीय आंग्ल-मैसूर युद्ध का अंत (टीपू सुल्तान व लॉर्ड मैकार्टनी के बीच)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (तेज बहादुर सप्रू व एम.आर. जयकर के प्रयासों से 5 मार्च 1931 को गांधी-इरविन समझौता हुआ।) युग्म 2 सही (मदन मोहन मालवीय व राजेंद्र प्रसाद के प्रयासों से गांधीजी की ओर से हस्ताक्षर व डॉ. आंबेडकर के बीच पूना पैक्ट हुआ।) युग्म 3 सही (मार्च 1784 की मंगलौर की संधि पर गवर्नर-जनरल वॉरेन हेस्टिंग्स ने कहा था: 'यह मैकार्टनी का पागलपन है'!)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: तेज बहादुर सप्रू व एम.आर. जयकर के प्रयासों से 5 मार्च 1931 को गांधी-इरविन समझौता हुआ।\nकथन-2: भारत छोड़ो आंदोलन को 'अगस्त क्रांति' भी कहा जाता है; भारतीय कम्युनिस्ट पार्टी (सोवियत संघ पर जर्मन हमले के बाद 'जनयुद्ध' नीति से), हिंदू महासभा व मुस्लिम लीग ने इसमें भाग नहीं लिया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) तेज बहादुर सप्रू व एम.आर. जयकर के प्रयासों से 5 मार्च 1931 को गांधी-इरविन समझौता हुआ। (2) भारत छोड़ो आंदोलन को 'अगस्त क्रांति' भी कहा जाता है; भारतीय कम्युनिस्ट पार्टी (सोवियत संघ पर जर्मन हमले के बाद 'जनयुद्ध' नीति से), हिंदू महासभा व मुस्लिम लीग ने इसमें भाग नहीं लिया।"},
  {"q":"ऐतिहासिक संदर्भ में 'अगस्त प्रस्ताव (अगस्त 1940 लिनलिथगो — युद्ध बाद संविधान सभा व अल्पसंख्यक वीटो, कांग्रेस ने ठुकराया); व्यक्तिगत सत्याग्रह (17 अक्टूबर 1940 पवनार आश्रम — प्रथम विनोबा भावे, द्वितीय नेहरू, तृतीय ब्रह्मदत्त — 'दिल्ली चलो आंदोलन'); क्रिप्स मिशन (मार्च 1942 — युद्ध बाद डोमिनियन स्टेटस व प्रांतों को अलग होने का विकल्प — गांधीजी ने 'पोस्ट-डेटेड चेक' कहा)' (प्रमुख मिशन व प्रस्ताव) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["(), एवं मिशन (1942)","भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो","वेवेल योजना (1945), कैबिनेट मिशन (1946) व माउंटबेटन योजना (1947)","सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946)"],"correct":0,"explanation":"गांधीजी ने क्रिप्स प्रस्ताव को 'दिवालिया बैंक का उत्तर-दिनांकित चेक (Post-dated cheque)' कहा, और नेहरू ने 'एक टूटते हुए बैंक के नाम' जोड़ा (हालांकि इतिहास में पहला वाक्य गांधीजी का प्रसिद्ध है)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. ब्रिटिश साम्राज्य के ताबूत में कील   B. गांधी-इरविन समझौता (1931), गोलमेज सम्मेलन व पूना पैक्ट (1932)\nC. क्रांतिकारी आंदोलन प्रथम चरण: महाराष्ट्र, बंगाल व विदेश में क्रांति   D. सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["ब्रिटिश साम्राज्य के ताबूत में कील","बोस, फौज (INA) एवं ()","क्रांतिकारी आंदोलन प्रथम चरण: महाराष्ट्र, बंगाल व विदेश में क्रांति","गांधी-इरविन समझौता (1931), गोलमेज सम्मेलन व पूना पैक्ट (1932)"],"correct":1,"explanation":"क्रांतिकारी आंदोलन प्रथम चरण: महाराष्ट्र, बंगाल व विदेश में क्रांति (1913 ई.), ब्रिटिश साम्राज्य के ताबूत में कील (1928 ई.), गांधी-इरविन समझौता (1931), गोलमेज सम्मेलन व पूना पैक्ट (1932) (1932 ई.), सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946) (1943 ई.)। अतः सबसे अंत में सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक नारे एवं उद्घोष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. करो या मरो (Do or Die)   |   1. रामप्रसाद बिस्मिल (रचना: बिस्मिल अजीमाबादी)\nB. स्वराज मेरा जन्मसिद्ध अधिकार है   |   2. महात्मा गांधी\nC. सरफरोशी की तमन्ना...   |   3. श्यामलाल गुप्त 'पार्षद'\nD. विजयी विश्व तिरंगा प्यारा   |   4. बाल गंगाधर तिलक","options":["A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1","A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3"],"correct":0,"explanation":"सही सुमेलन: करो या मरो (Do or Die) (महात्मा गांधी), स्वराज मेरा जन्मसिद्ध अधिकार है (बाल गंगाधर तिलक), सरफरोशी की तमन्ना... (रामप्रसाद बिस्मिल (रचना: बिस्मिल अजीमाबादी)), विजयी विश्व तिरंगा प्यारा (श्यामलाल गुप्त 'पार्षद')।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: ऐतिहासिक नारे एवं उद्घोष के अंतर्गत 'तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा' का ऐतिहासिक संबंध 'भगत सिंह (रचयिता: हसरत मोहानी)' से था।\nकथन-2: लॉर्ड लिनलिथगो ब्रिटिश भारत में सबसे लंबे समय (1936-1944) तक रहने वाले वायसराय थे।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा' का सही संबंध 'सुभाष चंद्र बोस' से था — नेताजी सुभाष चंद्र बोस ने दक्षिण-पूर्व एशिया में आजाद हिंद फौज के सैनिकों को प्रेरित करने हेतु यह आह्वान किया।)। कथन-2 सत्य है (लॉर्ड लिनलिथगो ब्रिटिश भारत में सबसे लंबे समय (1936-1944) तक रहने वाले वायसराय थे।)।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों पर विचार कीजिए:\n1. पूना समझौता / पूना पैक्ट (1932 ई.) : दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)\n2. इलाहाबाद की संधियाँ (1765 ई.) : ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति\n3. सुगौली की संधि (1816 ई.) : सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (मदन मोहन मालवीय व राजेंद्र प्रसाद के प्रयासों से गांधीजी की ओर से हस्ताक्षर व डॉ. आंबेडकर के बीच पूना पैक्ट हुआ।) युग्म 2 सही (बक्सर युद्ध के बाद इलाहाबाद की संधि से मुगल सम्राट ने कंपनी को बंगाल-बिहार-उड़ीसा की दीवानी दी।) युग्म 3 गलत (सही: सुगौली की संधि (1816 ई.) — आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1946 के कैबिनेट मिशन के तीन सदस्यों में सर जॉन साइमन, लॉर्ड माउंटबेटन और क्लीमेंट एटली शामिल थे जिन्होंने दो स्वतंत्र राज्यों की सिफारिश की।\nकथन-2: भारत के प्रथम शिक्षा मंत्री मौलाना आजाद ने विभाजन व आजादी के अंतिम वर्षों पर यह संस्मरण लिखा।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (कैबिनेट मिशन (1946) के तीन सदस्य लॉर्ड पैथिक लॉरेंस (भारत सचिव व अध्यक्ष), सर स्टैफोर्ड क्रिप्स और ए.वी. अलेक्जेंडर थे; इसने पाकिस्तान की माँग अस्वीकार की थी।)। कथन-2 सत्य है (भारत के प्रथम शिक्षा मंत्री मौलाना आजाद ने विभाजन व आजादी के अंतिम वर्षों पर यह संस्मरण लिखा।)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: जून 1945 के शिमला सम्मेलन की अध्यक्षता सुभाष चंद्र बोस ने की थी और इसमें पाकिस्तान के गठन पर अंतिम हस्ताक्षर हो गए थे।\nकथन-2: ऐतिहासिक नारे एवं उद्घोष के अंतर्गत 'सरफरोशी की तमन्ना...' का ऐतिहासिक संबंध 'जवाहरलाल नेहरू' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) जून-जुलाई 1945 के शिमला सम्मेलन की अध्यक्षता वायसराय लॉर्ड वेवेल ने की थी (कांग्रेस प्रतिनिधि मौलाना आजाद थे); जिन्ना के वीटो के कारण यह सम्मेलन असफल रहा। (2) 'सरफरोशी की तमन्ना...' का सही संबंध 'रामप्रसाद बिस्मिल (रचना: बिस्मिल अजीमाबादी)' से था — पटना के बिस्मिल अजीमाबादी द्वारा रचित यह गजल काकोरी नायक रामप्रसाद बिस्मिल ने अमर कर दी।"},
  {"q":"'तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा' और 'दिल्ली चलो' के आह्वान किसने दिए?","options":["महात्मा गांधी","लाला लाजपत राय","सुभाष चंद्र बोस","बाल गंगाधर तिलक"],"correct":2,"explanation":"नेताजी सुभाष चंद्र बोस ने दक्षिण-पूर्व एशिया में आजाद हिंद फौज के सैनिकों को प्रेरित करने हेतु यह आह्वान किया। उन्होंने 'जय हिंद' (आबिद हसन सफरानी के सुझाव पर लोकप्रिय) का नारा भी अपनाया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1944 के राजगोपालाचारी फॉर्मूले की विशेषता थी कि गांधीजी के समर्थन से कांग्रेस ने पहली बार व्यावहारिक रूप से आत्मनिर्णय के सिद्धांत को जनमत संग्रह की शर्त के साथ संवाद में लाया।\nकथन-2: 1935 के भारत शासन अधिनियम ने प्रांतों में 'द्वैध शासन' (Dyarchy) को पहली बार लागू किया तथा केंद्र में प्रांतीय स्वायत्तता लागू की।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (1944 के राजगोपालाचारी फॉर्मूले की विशेषता थी कि गांधीजी के समर्थन से कांग्रेस ने पहली बार व्यावहारिक रूप से आत्मनिर्णय के सिद्धांत को जनमत संग्रह की शर्त के साथ संवाद में लाया।)। कथन-2 गलत है — प्रांतों में 'द्वैध शासन' 1919 के अधिनियम ने लागू किया था; 1935 के अधिनियम ने प्रांतों से द्वैध शासन समाप्त कर उन्हें 'प्रांतीय स्वायत्तता' दी तथा केंद्र में द्वैध शासन प्रस्तावित किया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. ली आयोग (Lee Commission, 1923)   B. 1888 इलाहाबाद अधिवेशन\nC. राजगोपालाचारी फार्मूला (1944), देसाई-लियाकत व वेवेल शिमला सम्मेलन   D. वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग","ली आयोग (Lee Commission, 1923)","1888 इलाहाबाद अधिवेशन","(), व"],"correct":3,"explanation":"वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग (1875 ई.), 1888 इलाहाबाद अधिवेशन (1888 ई.), ली आयोग (Lee Commission, 1923) (1923 ई.), राजगोपालाचारी फार्मूला (1944), देसाई-लियाकत व वेवेल शिमला सम्मेलन (1945 ई.)। अतः सबसे अंत में राजगोपालाचारी फार्मूला (1944), देसाई-लियाकत व वेवेल शिमला सम्मेलन।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. भारत में प्रथम नियमित (दशकीय) जनगणना 1881 में लॉर्ड लिटन के समय हुई तथा स्थानीय स्वशासन का जनक लॉर्ड मेयो को कहा जाता है।\n2. 15 अगस्त 1947 को जब भारत स्वतंत्र हुआ तब कांग्रेस के अध्यक्ष आचार्य जे.बी. कृपलानी थे।\n3. संवैधानिक अधिनियम एवं प्रावधान के अंतर्गत 'भारत शासन अधिनियम, 1935' का ऐतिहासिक संबंध 'गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ' से था।\n4. क्रांतिकारी घटनाएँ एवं नायक के अंतर्गत 'माइकल ओ डायर वध (1940)' का ऐतिहासिक संबंध 'खुदीराम बोस एवं प्रफुल्ल चाकी' से था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (15 अगस्त 1947 को जब भारत स्वतंत्र हुआ तब कांग्रेस के अध्यक्ष आचार्य जे.बी. कृपलानी थे।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. भारत के प्रथम शिक्षा मंत्री मौलाना आजाद ने विभाजन व आजादी के अंतिम वर्षों पर यह संस्मरण लिखा।\n2. एंड्रयू फ्रेजर की अध्यक्षता वाले आयोग की सिफारिश पर सभी प्रांतों में पुलिस व गुप्तचर (CID) विभाग बने।\n3. कांग्रेस अधिवेशन एवं अध्यक्ष के अंतर्गत '1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)' का ऐतिहासिक संबंध 'व्योमेश चंद्र बनर्जी' से था।\n4. सरदार पटेल की अध्यक्षता में हुए कराची अधिवेशन में गांधी-इरविन समझौते का समर्थन व मूल अधिकार प्रस्ताव पास हुआ।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: '1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)' का सही संबंध 'आचार्य जे.बी. कृपलानी' से था — 15 अगस्त 1947 को जब भारत स्वतंत्र हुआ तब कांग्रेस के अध्यक्ष आचार्य जे.बी. कृपलानी थे।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा   B. मेरे शरीर पर पड़ी एक-एक लाठी...\nC. करो या मरो (Do or Die)   D. स्वराज पार्टी (1923), साइमन कमीशन (1927) व नेहरू रिपोर्ट (1928)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["तुम खून दो, मैं","मेरे शरीर पर पड़ी एक-एक लाठी...","स्वराज पार्टी (1923), साइमन कमीशन (1927) व नेहरू रिपोर्ट (1928)","करो या मरो (Do or Die)"],"correct":0,"explanation":"स्वराज पार्टी (1923), साइमन कमीशन (1927) व नेहरू रिपोर्ट (1928) (1923 ई.), मेरे शरीर पर पड़ी एक-एक लाठी... (1928 ई.), करो या मरो (Do or Die) (1942 ई.), तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा (1944 ई.)। अतः सबसे अंत में तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत)   B. 1929 लाहौर अधिवेशन\nC. कांग्रेस-पूर्व राजनीतिक संगठन (1836–1885)   D. करो या मरो (Do or Die)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत)","कांग्रेस-पूर्व राजनीतिक संगठन (1836–1885)","1929 लाहौर अधिवेशन","करो या मरो (Do or Die)"],"correct":3,"explanation":"कांग्रेस-पूर्व राजनीतिक संगठन (1836–1885) (1876 ई.), सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) (1927 ई.), 1929 लाहौर अधिवेशन (1929 ई.), करो या मरो (Do or Die) (1942 ई.)। अतः सबसे अंत में करो या मरो (Do or Die)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. भारत परिषद अधिनियम 1861, 1892 एवं मार्ले-मिंटो सुधार 1909   B. केंद्रीय असेंबली बम कांड (1929)\nC. स्वराज पार्टी (1923), साइमन कमीशन (1927) व नेहरू रिपोर्ट (1928)   D. तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["केंद्रीय असेंबली बम कांड (1929)","भारत परिषद अधिनियम 1861, 1892 एवं मार्ले-मिंटो सुधार 1909","तुम खून दो, मैं","स्वराज पार्टी (1923), साइमन कमीशन (1927) व नेहरू रिपोर्ट (1928)"],"correct":2,"explanation":"भारत परिषद अधिनियम 1861, 1892 एवं मार्ले-मिंटो सुधार 1909 (1909 ई.), स्वराज पार्टी (1923), साइमन कमीशन (1927) व नेहरू रिपोर्ट (1928) (1923 ई.), केंद्रीय असेंबली बम कांड (1929) (1929 ई.), तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा (1944 ई.)। अतः सबसे अंत में तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. अगस्त प्रस्ताव (1940), व्यक्तिगत सत्याग्रह एवं क्रिप्स मिशन (1942)   B. हंटर शिक्षा आयोग (1882)\nC. ह्विटली आयोग (1929 ई.)   D. सरफरोशी की तमन्ना...\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["(), एवं ()","हंटर शिक्षा आयोग (1882)","ह्विटली आयोग (1929 ई.)","सरफरोशी की तमन्ना..."],"correct":0,"explanation":"हंटर शिक्षा आयोग (1882) (1882 ई.), सरफरोशी की तमन्ना... (1927 ई.), ह्विटली आयोग (1929 ई.) (1929 ई.), अगस्त प्रस्ताव (1940), व्यक्तिगत सत्याग्रह एवं क्रिप्स मिशन (1942) (1940 ई.)। अतः सबसे अंत में अगस्त प्रस्ताव (1940), व्यक्तिगत सत्याग्रह एवं क्रिप्स मिशन (1942)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. 1940 रामगढ़ अधिवेशन   B. लॉर्ड मेयो (1869-72)\nC. द इंडियन वार ऑफ इंडिपेंडेंस 1857   D. लॉर्ड कर्जन (1899-1905)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["द इंडियन वार ऑफ इंडिपेंडेंस 1857","लॉर्ड मेयो (1869-72)","लॉर्ड कर्जन (1899-1905)","अधिवेशन"],"correct":3,"explanation":"लॉर्ड मेयो (1869-72) (1872 ई.), लॉर्ड कर्जन (1899-1905) (1905 ई.), द इंडियन वार ऑफ इंडिपेंडेंस 1857 (1909 ई.), 1940 रामगढ़ अधिवेशन (1940 ई.)। अतः सबसे अंत में 1940 रामगढ़ अधिवेशन।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: ऐतिहासिक नारे एवं उद्घोष के अंतर्गत 'तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा' का ऐतिहासिक संबंध 'भगत सिंह (रचयिता: हसरत मोहानी)' से था।\nकथन-2: प्रमुख आयोग एवं उद्देश्य के अंतर्गत 'ली आयोग (Lee Commission, 1923)' का ऐतिहासिक संबंध 'बंगाल में स्थायी बंदोबस्त (जमींदारी) की समाप्ति की सिफारिश व बटाईदारों को 2/3 हिस्सा' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा' का सही संबंध 'सुभाष चंद्र बोस' से था — नेताजी सुभाष चंद्र बोस ने दक्षिण-पूर्व एशिया में आजाद हिंद फौज के सैनिकों को प्रेरित करने हेतु यह आह्वान किया। (2) 'ली आयोग (Lee Commission, 1923)' का सही संबंध 'अखिल भारतीय सिविल सेवा में भारतीय व ब्रिटिश 50-50 अनुपात' से था — लॉर्ड ली की अध्यक्षता में आयोग ने 15 वर्षों में ICS में 50% भारतीय करने व लोक सेवा आयोग (1926) बनाने की सिफारिश की।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों पर विचार कीजिए:\n1. पूना समझौता / पूना पैक्ट (1932 ई.) : दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)\n2. इलाहाबाद की संधियाँ (1765 ई.) : प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी\n3. एक्स-ला-शैपल की संधि (1748 ई.) : महाराजा रणजीत सिंह और लॉर्ड मिंटो प्रथम (चार्ल्स मेटकाफ) — सतलज नदी सीमा तय\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (मदन मोहन मालवीय व राजेंद्र प्रसाद के प्रयासों से गांधीजी की ओर से हस्ताक्षर व डॉ. आंबेडकर के बीच पूना पैक्ट हुआ।) युग्म 2 गलत (सही: इलाहाबाद की संधियाँ (1765 ई.) — ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति)। युग्म 3 गलत (सही: एक्स-ला-शैपल की संधि (1748 ई.) — प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी)।"},
  {"q":"1940 के रामगढ़ (झारखंड) कांग्रेस अधिवेशन की अध्यक्षता किसने की थी?","options":["जॉर्ज यूल (प्रथम अंग्रेज अध्यक्ष)","व्योमेश चंद्र बनर्जी","मौलाना अबुल कलाम आजाद","बदरुद्दीन तैयबजी (प्रथम मुस्लिम अध्यक्ष)"],"correct":2,"explanation":"1940 के रामगढ़ अधिवेशन में मौलाना आजाद अध्यक्ष बने और विश्व युद्ध संकट के कारण 1940-46 तक लगातार अध्यक्ष रहे। द्वितीय विश्व युद्ध व भारत छोड़ो के कारण लगातार 6 वर्ष चुनाव नहीं हो सके।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. विजयी विश्व तिरंगा प्यारा   B. 1929 लाहौर अधिवेशन\nC. सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946)   D. गांधी-इरविन समझौता (1931 ई.)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["1929 लाहौर अधिवेशन","बोस, फौज (INA) एवं ()","विजयी विश्व तिरंगा प्यारा","गांधी-इरविन समझौता (1931 ई.)"],"correct":1,"explanation":"विजयी विश्व तिरंगा प्यारा (1924 ई.), 1929 लाहौर अधिवेशन (1929 ई.), गांधी-इरविन समझौता (1931 ई.) (1931 ई.), सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946) (1943 ई.)। अतः सबसे अंत में सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946)।"},
  {"q":"भारत की स्वतंत्रता के समय (नवंबर 1946 मेरठ अधिवेशन से 1947 तक) कांग्रेस अध्यक्ष कौन थे?","options":["बदरुद्दीन तैयबजी (प्रथम मुस्लिम अध्यक्ष)","जॉर्ज यूल (प्रथम अंग्रेज अध्यक्ष)","आचार्य जे.बी. कृपलानी","व्योमेश चंद्र बनर्जी"],"correct":2,"explanation":"15 अगस्त 1947 को जब भारत स्वतंत्र हुआ तब कांग्रेस के अध्यक्ष आचार्य जे.बी. कृपलानी थे। उनके इस्तीफे के बाद नवंबर 1947 में डॉ. राजेंद्र प्रसाद अध्यक्ष बने।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. 1896 कलकत्ता अधिवेशन   B. सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946)\nC. लॉर्ड कैनिंग, मेयो, लिटन, रिपन एवं लॉर्ड कर्जन   D. 1916 लखनऊ अधिवेशन\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["लॉर्ड कैनिंग, मेयो, लिटन, रिपन एवं लॉर्ड कर्जन","बोस, फौज","1896 कलकत्ता अधिवेशन","1916 लखनऊ अधिवेशन"],"correct":1,"explanation":"लॉर्ड कैनिंग, मेयो, लिटन, रिपन एवं लॉर्ड कर्जन (1882 ई.), 1896 कलकत्ता अधिवेशन (1896 ई.), 1916 लखनऊ अधिवेशन (1916 ई.), सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946) (1943 ई.)। अतः सबसे अंत में सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: भारत छोड़ो आंदोलन को 'अगस्त क्रांति' भी कहा जाता है; भारतीय कम्युनिस्ट पार्टी (सोवियत संघ पर जर्मन हमले के बाद 'जनयुद्ध' नीति से), हिंदू महासभा व मुस्लिम लीग ने इसमें भाग नहीं लिया।\nकथन-2: कर्नाटक के बेलगाम में 1924 में महात्मा गांधी ने जीवन में केवल एक बार कांग्रेस अध्यक्षता की।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) भारत छोड़ो आंदोलन को 'अगस्त क्रांति' भी कहा जाता है; भारतीय कम्युनिस्ट पार्टी (सोवियत संघ पर जर्मन हमले के बाद 'जनयुद्ध' नीति से), हिंदू महासभा व मुस्लिम लीग ने इसमें भाग नहीं लिया। (2) कर्नाटक के बेलगाम में 1924 में महात्मा गांधी ने जीवन में केवल एक बार कांग्रेस अध्यक्षता की।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. 30 अक्टूबर 1928 को लाहौर में स्कॉट-सॉन्डर्स के लाठीचार्ज में घायल 'पंजाब केसरी' ने यह कहा।\n2. सरदार वल्लभभाई पटेल और वी.पी. मेनन की कूटनीति से 15 अगस्त 1947 से पूर्व ही तीन को छोड़कर लगभग सभी देसी रियासतों ने भारत में विलय पत्र पर हस्ताक्षर कर दिए थे।\n3. प्रमुख संधियाँ एवं समझौते के अंतर्गत 'गांधी-इरविन समझौता (1931 ई.)' का ऐतिहासिक संबंध 'दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)' से था।\n4. 15 अगस्त 1947 को गठित स्वतंत्र भारत के प्रथम मंत्रिमंडल में न केवल कांग्रेसी बल्कि डॉ. बी.आर. अंबेडकर, डॉ. श्यामा प्रसाद मुखर्जी और जॉन मथाई जैसे गैर-कांग्रेसी विशेषज्ञ भी शामिल थे।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: 'गांधी-इरविन समझौता (1931 ई.)' का सही संबंध 'सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी' से था — तेज बहादुर सप्रू व एम.आर. जयकर के प्रयासों से 5 मार्च 1931 को गांधी-इरविन समझौता हुआ।"},
  {"q":"[UPSC Prelims पैटर्न — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) : व्योमेश चंद्र बनर्जी\n2. 1885 बंबई अधिवेशन (प्रथम) : बदरुद्दीन तैयबजी (प्रथम मुस्लिम अध्यक्ष)\n3. 1887 मद्रास अधिवेशन : महात्मा गांधी\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) — आचार्य जे.बी. कृपलानी)। युग्म 2 गलत (सही: 1885 बंबई अधिवेशन (प्रथम) — व्योमेश चंद्र बनर्जी)। युग्म 3 गलत (सही: 1887 मद्रास अधिवेशन — बदरुद्दीन तैयबजी (प्रथम मुस्लिम अध्यक्ष))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — कांग्रेस अधिवेशन एवं अध्यक्ष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)   |   1. पं. बिशन नारायण धर\nB. 1887 मद्रास अधिवेशन   |   2. महात्मा गांधी\nC. 1924 बेलगाम अधिवेशन   |   3. आचार्य जे.बी. कृपलानी\nD. 1911 कलकत्ता अधिवेशन   |   4. बदरुद्दीन तैयबजी (प्रथम मुस्लिम अध्यक्ष)","options":["A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1"],"correct":0,"explanation":"सही सुमेलन: 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) (आचार्य जे.बी. कृपलानी), 1887 मद्रास अधिवेशन (बदरुद्दीन तैयबजी (प्रथम मुस्लिम अध्यक्ष)), 1924 बेलगाम अधिवेशन (महात्मा गांधी), 1911 कलकत्ता अधिवेशन (पं. बिशन नारायण धर)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: ऐतिहासिक नारे एवं उद्घोष के अंतर्गत 'तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा' का ऐतिहासिक संबंध 'भगत सिंह (रचयिता: हसरत मोहानी)' से था।\nकथन-2: लॉर्ड ली की अध्यक्षता में आयोग ने 15 वर्षों में ICS में 50% भारतीय करने व लोक सेवा आयोग (1926) बनाने की सिफारिश की।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा' का सही संबंध 'सुभाष चंद्र बोस' से था — नेताजी सुभाष चंद्र बोस ने दक्षिण-पूर्व एशिया में आजाद हिंद फौज के सैनिकों को प्रेरित करने हेतु यह आह्वान किया।)। कथन-2 सत्य है (लॉर्ड ली की अध्यक्षता में आयोग ने 15 वर्षों में ICS में 50% भारतीय करने व लोक सेवा आयोग (1926) बनाने की सिफारिश की।)।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों पर विचार कीजिए:\n1. गांधी-इरविन समझौता (1931 ई.) : सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी\n2. मद्रास की संधि (1769 ई.) : प्रथम आंग्ल-मैसूर युद्ध की समाप्ति (विजित क्षेत्रों की वापसी व पारस्परिक रक्षा समझौता)\n3. पूना समझौता / पूना पैक्ट (1932 ई.) : दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (तेज बहादुर सप्रू व एम.आर. जयकर के प्रयासों से 5 मार्च 1931 को गांधी-इरविन समझौता हुआ।) युग्म 2 सही (अप्रैल 1769 की मद्रास संधि से प्रथम आंग्ल-मैसूर युद्ध समाप्त हुआ जिसमें हैदर अली का पलड़ा भारी रहा।) युग्म 3 सही (मदन मोहन मालवीय व राजेंद्र प्रसाद के प्रयासों से गांधीजी की ओर से हस्ताक्षर व डॉ. आंबेडकर के बीच पूना पैक्ट हुआ।)।"},
  {"q":"[PSC/CDS युग्म पहचान — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. करो या मरो (Do or Die) : महात्मा गांधी\n2. सरफरोशी की तमन्ना... : बाल गंगाधर तिलक\n3. स्वराज मेरा जन्मसिद्ध अधिकार है : श्यामलाल गुप्त 'पार्षद'\n4. विजयी विश्व तिरंगा प्यारा : लाला लाजपत राय","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: 8 अगस्त 1942 को बंबई के ग्वालिया टैंक मैदान में गांधीजी ने अंतिम अहिंसक संग्राम हेतु 'करो या मरो' मंत्र दिया। (अन्य सही युग्म: सरफरोशी की तमन्ना...→रामप्रसाद बिस्मिल (रचना: बिस्मिल अजीमाबादी), स्वराज मेरा जन्मसिद्ध अधिकार है→बाल गंगाधर तिलक, विजयी विश्व तिरंगा प्यारा→श्यामलाल गुप्त 'पार्षद')।"},
  {"q":"[PSC/CDS युग्म पहचान — प्रमुख संधियाँ एवं समझौते] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. गांधी-इरविन समझौता (1931 ई.) : सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी\n2. एक्स-ला-शैपल की संधि (1748 ई.) : प्रथम आंग्ल-मैसूर युद्ध की समाप्ति (विजित क्षेत्रों की वापसी व पारस्परिक रक्षा समझौता)\n3. मद्रास की संधि (1769 ई.) : प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)\n4. यांडबू की संधि (1826 ई.) : दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: तेज बहादुर सप्रू व एम.आर. जयकर के प्रयासों से 5 मार्च 1931 को गांधी-इरविन समझौता हुआ। (अन्य सही युग्म: एक्स-ला-शैपल की संधि (1748 ई.)→प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी, मद्रास की संधि (1769 ई.)→प्रथम आंग्ल-मैसूर युद्ध की समाप्ति (विजित क्षेत्रों की वापसी व पारस्परिक रक्षा समझौता), यांडबू की संधि (1826 ई.)→प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 8 अगस्त 1942 को बंबई के ग्वालिया टैंक मैदान में गांधीजी ने अंतिम अहिंसक संग्राम हेतु 'करो या मरो' मंत्र दिया।\nकथन-2: 23 दिसंबर 1912 को राजधानी प्रवेश जुलूस में हार्डिंग पर बम फेंका गया; रासबिहारी बोस बाद में जापान चले गए।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) 8 अगस्त 1942 को बंबई के ग्वालिया टैंक मैदान में गांधीजी ने अंतिम अहिंसक संग्राम हेतु 'करो या मरो' मंत्र दिया। (2) 23 दिसंबर 1912 को राजधानी प्रवेश जुलूस में हार्डिंग पर बम फेंका गया; रासबिहारी बोस बाद में जापान चले गए।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. अगस्त प्रस्ताव (1940), व्यक्तिगत सत्याग्रह एवं क्रिप्स मिशन (1942)   B. केंद्रीय असेंबली बम कांड (1929)\nC. 1917 कलकत्ता अधिवेशन   D. सरफरोशी की तमन्ना...\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["केंद्रीय असेंबली बम कांड (1929)","सरफरोशी की तमन्ना...","1917 कलकत्ता अधिवेशन","(), एवं ()"],"correct":3,"explanation":"1917 कलकत्ता अधिवेशन (1917 ई.), सरफरोशी की तमन्ना... (1927 ई.), केंद्रीय असेंबली बम कांड (1929) (1929 ई.), अगस्त प्रस्ताव (1940), व्यक्तिगत सत्याग्रह एवं क्रिप्स मिशन (1942) (1940 ई.)। अतः सबसे अंत में अगस्त प्रस्ताव (1940), व्यक्तिगत सत्याग्रह एवं क्रिप्स मिशन (1942)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा : लाला लाजपत राय\n2. स्वराज मेरा जन्मसिद्ध अधिकार है : बाल गंगाधर तिलक\n3. करो या मरो (Do or Die) : महात्मा गांधी\n4. विजयी विश्व तिरंगा प्यारा : श्यामलाल गुप्त 'पार्षद'","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा' का सही संबंध 'सुभाष चंद्र बोस' से है (न कि 'लाला लाजपत राय' से)। नेताजी सुभाष चंद्र बोस ने दक्षिण-पूर्व एशिया में आजाद हिंद फौज के सैनिकों को प्रेरित करने हेतु यह आह्वान किया।"},
  {"q":"[UPSC/PCS सूची सुमेलन — कांग्रेस अधिवेशन एवं अध्यक्ष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)   |   1. सरोजिनी नायडू (प्रथम भारतीय महिला)\nB. 1896 कलकत्ता अधिवेशन   |   2. आचार्य जे.बी. कृपलानी\nC. 1925 कानपुर अधिवेशन   |   3. अंबिका चरण मजूमदार\nD. 1916 लखनऊ अधिवेशन   |   4. रहीमतुल्ला एम. सयानी","options":["A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3"],"correct":1,"explanation":"सही सुमेलन: 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) (आचार्य जे.बी. कृपलानी), 1896 कलकत्ता अधिवेशन (रहीमतुल्ला एम. सयानी), 1925 कानपुर अधिवेशन (सरोजिनी नायडू (प्रथम भारतीय महिला)), 1916 लखनऊ अधिवेशन (अंबिका चरण मजूमदार)।"},
  {"q":"24 सितंबर 1932 का प्रसिद्ध 'पूना पैक्ट' (यरवदा जेल में) किन दोनों पक्षों के बीच हुआ?","options":["प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी","तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत","ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति","दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें"],"correct":3,"explanation":"मदन मोहन मालवीय व राजेंद्र प्रसाद के प्रयासों से गांधीजी की ओर से हस्ताक्षर व डॉ. आंबेडकर के बीच पूना पैक्ट हुआ। गांधीजी ने रैम्जे मैकडोनाल्ड के 'साम्प्रदायिक पंचाट' के विरुद्ध यरवदा जेल में आमरण अनशन किया था। [71 से 147]"},
  {"q":"[PSC/CDS युग्म विश्लेषण — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. पूना समझौता / पूना पैक्ट (1932 ई.) : पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना\n2. इलाहाबाद की संधियाँ (1765 ई.) : ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति\n3. गांधी-इरविन समझौता (1931 ई.) : सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी\n4. पेरिस की संधि (1763 ई.) : तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'पूना समझौता / पूना पैक्ट (1932 ई.)' का सही संबंध 'दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)' से है (न कि 'पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना' से)। मदन मोहन मालवीय व राजेंद्र प्रसाद के प्रयासों से गांधीजी की ओर से हस्ताक्षर व डॉ. आंबेडकर के बीच पूना पैक्ट हुआ।"},
  {"q":"[UPSC Prelims पैटर्न — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) : मौलाना अबुल कलाम आजाद\n2. 1940 रामगढ़ अधिवेशन : अंबिका चरण मजूमदार\n3. 1916 लखनऊ अधिवेशन : जॉर्ज यूल (प्रथम अंग्रेज अध्यक्ष)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) — आचार्य जे.बी. कृपलानी)। युग्म 2 गलत (सही: 1940 रामगढ़ अधिवेशन — मौलाना अबुल कलाम आजाद)। युग्म 3 गलत (सही: 1916 लखनऊ अधिवेशन — अंबिका चरण मजूमदार)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. भारतीय परिषद अधिनियम, 1909   B. सरफरोशी की तमन्ना...\nC. रौलेट एक्ट, जलियाँवाला बाग, खिलाफत व असहयोग आंदोलन (1919–1922)   D. भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["रौलेट एक्ट, जलियाँवाला बाग, खिलाफत व असहयोग आंदोलन (1919–1922)","भारत आंदोलन (), व","भारतीय परिषद अधिनियम, 1909","सरफरोशी की तमन्ना..."],"correct":1,"explanation":"भारतीय परिषद अधिनियम, 1909 (1909 ई.), रौलेट एक्ट, जलियाँवाला बाग, खिलाफत व असहयोग आंदोलन (1919–1922) (1919 ई.), सरफरोशी की तमन्ना... (1927 ई.), भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो (1942 ई.)। अतः सबसे अंत में भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) : अंबिका चरण मजूमदार\n2. 1940 रामगढ़ अधिवेशन : मौलाना अबुल कलाम आजाद\n3. 1911 कलकत्ता अधिवेशन : पं. बिशन नारायण धर\n4. 1887 मद्रास अधिवेशन : बदरुद्दीन तैयबजी (प्रथम मुस्लिम अध्यक्ष)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: '1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)' का सही संबंध 'आचार्य जे.बी. कृपलानी' से है (न कि 'अंबिका चरण मजूमदार' से)। 15 अगस्त 1947 को जब भारत स्वतंत्र हुआ तब कांग्रेस के अध्यक्ष आचार्य जे.बी. कृपलानी थे।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. 1892 के अधिनियम में 'निर्वाचन' शब्द नहीं था, किंतु जिला बोर्ड/विश्वविद्यालयों द्वारा परोक्ष चुनाव प्रणाली आरंभ हुई।\n2. इंडिया हाउस से जुड़े मदनलाल धींगरा ने 1 जुलाई 1909 को लंदन में कर्जन वायली को गोली मारी।\n3. अक्टूबर 1940 में प्रारंभ हुए 'व्यक्तिगत सत्याग्रह' के प्रथम सत्याग्रही जवाहरलाल नेहरू तथा द्वितीय सरदार वल्लभभाई पटेल थे।\n4. सर हरकोर्ट बटलर की अध्यक्षता वाली समिति ने कहा कि देसी रियासतें बिना सहमति ब्रिटिश भारतीय उत्तरदायी सरकार को न सौंपी जाएँ।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: अक्टूबर 1940 के व्यक्तिगत सत्याग्रह के प्रथम सत्याग्रही आचार्य विनोबा भावे, द्वितीय जवाहरलाल नेहरू तथा तृतीय ब्रह्मदत्त थे।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: आजाद हिंद फौज (INA) की पहली सैन्य स्थापना 1943 में बर्लिन में रासबिहारी बोस की बजाय सरदार भगत सिंह के नेतृत्व में हुई थी।\nकथन-2: 1887 मद्रास अधिवेशन में बदरुद्दीन तैयबजी ने कांग्रेस के धर्मनिरपेक्ष स्वरूप को सुदृढ़ किया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (आजाद हिंद फौज (INA) की प्रथम स्थापना का विचार व गठन 1942 में दक्षिण-पूर्व एशिया (मलय) में कैप्टन मोहन सिंह व जापानी मेजर फुजिवारा की सहायता से हुआ, जिसे 1943 में रासबिहारी बोस ने सुभाष को सौंपा।)। कथन-2 सत्य है (1887 मद्रास अधिवेशन में बदरुद्दीन तैयबजी ने कांग्रेस के धर्मनिरपेक्ष स्वरूप को सुदृढ़ किया।)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: प्रमुख संधियाँ एवं समझौते के अंतर्गत 'पूना समझौता / पूना पैक्ट (1932 ई.)' का ऐतिहासिक संबंध 'प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी' से था।\nकथन-2: लॉर्ड लिनलिथगो ब्रिटिश भारत में सबसे लंबे समय (1936-1944) तक रहने वाले वायसराय थे।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('पूना समझौता / पूना पैक्ट (1932 ई.)' का सही संबंध 'दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)' से था — मदन मोहन मालवीय व राजेंद्र प्रसाद के प्रयासों से गांधीजी की ओर से हस्ताक्षर व डॉ. आंबेडकर के बीच पूना पैक्ट हुआ।)। कथन-2 सत्य है (लॉर्ड लिनलिथगो ब्रिटिश भारत में सबसे लंबे समय (1936-1944) तक रहने वाले वायसराय थे।)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. सालबाई की संधि (1782 ई.) : प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति)\n2. एक्स-ला-शैपल की संधि (1748 ई.) : प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी\n3. गांधी-इरविन समझौता (1931 ई.) : दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)\n4. बसीन की संधि (1802 ई.) : पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'गांधी-इरविन समझौता (1931 ई.)' का सही संबंध 'सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी' से है (न कि 'दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)' से)। तेज बहादुर सप्रू व एम.आर. जयकर के प्रयासों से 5 मार्च 1931 को गांधी-इरविन समझौता हुआ।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. मेरे शरीर पर पड़ी एक-एक लाठी... : लाला लाजपत राय\n2. आराम हराम है / Who lives if India dies : जवाहरलाल नेहरू\n3. करो या मरो (Do or Die) : रामप्रसाद बिस्मिल (रचना: बिस्मिल अजीमाबादी)\n4. स्वराज मेरा जन्मसिद्ध अधिकार है : बाल गंगाधर तिलक","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'करो या मरो (Do or Die)' का सही संबंध 'महात्मा गांधी' से है (न कि 'रामप्रसाद बिस्मिल (रचना: बिस्मिल अजीमाबादी)' से)। 8 अगस्त 1942 को बंबई के ग्वालिया टैंक मैदान में गांधीजी ने अंतिम अहिंसक संग्राम हेतु 'करो या मरो' मंत्र दिया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. अखिल भारतीय किसान सभा (1936), ट्रेड यूनियन (AITUC) व वामपंथ   B. लॉर्ड मेयो (1869-72)\nC. सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946)   D. वेवेल योजना (1945), कैबिनेट मिशन (1946) व माउंटबेटन योजना (1947)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946)","अखिल भारतीय किसान सभा (1936), ट्रेड यूनियन (AITUC) व वामपंथ","लॉर्ड मेयो (1869-72)","(), (1946) व ()"],"correct":3,"explanation":"लॉर्ड मेयो (1869-72) (1872 ई.), अखिल भारतीय किसान सभा (1936), ट्रेड यूनियन (AITUC) व वामपंथ (1936 ई.), सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946) (1943 ई.), वेवेल योजना (1945), कैबिनेट मिशन (1946) व माउंटबेटन योजना (1947) (1946 ई.)। अतः सबसे अंत में वेवेल योजना (1945), कैबिनेट मिशन (1946) व माउंटबेटन योजना (1947)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. गांधी-इरविन समझौता (1931 ई.)   B. मेरे शरीर पर पड़ी एक-एक लाठी...\nC. भारत परिषद अधिनियम 1861, 1892 एवं मार्ले-मिंटो सुधार 1909   D. सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["भारत परिषद अधिनियम 1861, 1892 एवं मार्ले-मिंटो सुधार 1909","मेरे शरीर पर पड़ी एक-एक लाठी...","सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)","(ई.)"],"correct":3,"explanation":"भारत परिषद अधिनियम 1861, 1892 एवं मार्ले-मिंटो सुधार 1909 (1909 ई.), सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916) (1917 ई.), मेरे शरीर पर पड़ी एक-एक लाठी... (1928 ई.), गांधी-इरविन समझौता (1931 ई.) (1931 ई.)। अतः सबसे अंत में गांधी-इरविन समझौता (1931 ई.)।"},
  {"q":"ऐतिहासिक संदर्भ में 'सी.आर. फार्मूला (1944 — कांग्रेस-लीग सहयोग व युद्धोपरांत मुस्लिम बहुल सीमांत जिलों में जनमत संग्रह; जिन्ना ने 'कीड़े खाया पाकिस्तान' कहकर ठुकराया); गांधी-जिन्ना वार्ता (सितंबर 1944); शिमला सम्मेलन (जून 1945 — मुस्लिम लीग की सभी मुस्लिम सीटें नामित करने की जिद से विफल)' (राजनीतिक समझौते के प्रयास) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["राजगोपालाचारी (), देसाई-लियाकत व वेवेल","अगस्त प्रस्ताव (1940), व्यक्तिगत सत्याग्रह एवं क्रिप्स मिशन (1942)","भारत छोड़ो आंदोलन (1942), समानांतर सरकारें व भूमिगत रेडियो","सुभाष चंद्र बोस, आजाद हिंद फौज (INA) एवं नौसेना विद्रोह (1946)"],"correct":0,"explanation":"1945-46 के आम चुनावों में कांग्रेस ने सामान्य सीटों में भारी बहुमत जीता (91% गैर-मुस्लिम मत) जबकि मुस्लिम लीग ने केंद्र की सभी 30 और प्रांतों की अधिकांश आरक्षित मुस्लिम सीटें जीतीं।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. 1924 बेलगाम अधिवेशन : महात्मा गांधी\n2. 1929 लाहौर अधिवेशन : पं. जवाहरलाल नेहरू\n3. 1940 रामगढ़ अधिवेशन : व्योमेश चंद्र बनर्जी\n4. 1911 कलकत्ता अधिवेशन : पं. बिशन नारायण धर","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: '1940 रामगढ़ अधिवेशन' का सही संबंध 'मौलाना अबुल कलाम आजाद' से है (न कि 'व्योमेश चंद्र बनर्जी' से)। 1940 के रामगढ़ अधिवेशन में मौलाना आजाद अध्यक्ष बने और विश्व युद्ध संकट के कारण 1940-46 तक लगातार अध्यक्ष रहे।"},
  {"q":"[UPSC/PCS सूची सुमेलन — प्रमुख संधियाँ एवं समझौते] सूची-I को सूची-II से सुमेलित कीजिए:\nA. पूना समझौता / पूना पैक्ट (1932 ई.)   |   1. प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति)\nB. सुगौली की संधि (1816 ई.)   |   2. पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना\nC. बसीन की संधि (1802 ई.)   |   3. दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)\nD. सालबाई की संधि (1782 ई.)   |   4. आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)","options":["A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-3, B-2, C-4, D-1"],"correct":1,"explanation":"सही सुमेलन: पूना समझौता / पूना पैक्ट (1932 ई.) (दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)), सुगौली की संधि (1816 ई.) (आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)), बसीन की संधि (1802 ई.) (पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना), सालबाई की संधि (1782 ई.) (प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 15 अगस्त 1947 को जब भारत स्वतंत्र हुआ तब कांग्रेस के अध्यक्ष आचार्य जे.बी. कृपलानी थे।\nकथन-2: ऐतिहासिक नारे एवं उद्घोष के अंतर्गत 'इंकलाब जिंदाबाद' का ऐतिहासिक संबंध 'रामप्रसाद बिस्मिल (रचना: बिस्मिल अजीमाबादी)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (15 अगस्त 1947 को जब भारत स्वतंत्र हुआ तब कांग्रेस के अध्यक्ष आचार्य जे.बी. कृपलानी थे।)। कथन-2 गलत है — 'इंकलाब जिंदाबाद' का सही संबंध 'भगत सिंह (रचयिता: हसरत मोहानी)' से था — मूलतः मौलाना हसरत मोहानी (1921) द्वारा रचित इस नारे को भगत सिंह व बटुकेश्वर दत्त ने 1929 में अमर किया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. अनहैप्पी इंडिया (1928)   B. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)\nC. द इंडियन स्ट्रगल   D. विजयी विश्व तिरंगा प्यारा\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["विजयी विश्व तिरंगा प्यारा","द इंडियन स्ट्रगल","अनहैप्पी इंडिया (1928)","(समय )"],"correct":3,"explanation":"विजयी विश्व तिरंगा प्यारा (1924 ई.), अनहैप्पी इंडिया (1928) (1928 ई.), द इंडियन स्ट्रगल (1935 ई.), 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) (1946 ई.)। अतः सबसे अंत में 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. ली आयोग (Lee Commission, 1923)   B. तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा\nC. 1924 बेलगाम अधिवेशन   D. भारतीय परिषद अधिनियम, 1909\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["भारतीय परिषद अधिनियम, 1909","तुम खून दो, मैं","1924 बेलगाम अधिवेशन","ली आयोग (Lee Commission, 1923)"],"correct":1,"explanation":"भारतीय परिषद अधिनियम, 1909 (1909 ई.), ली आयोग (Lee Commission, 1923) (1923 ई.), 1924 बेलगाम अधिवेशन (1924 ई.), तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा (1944 ई.)। अतः सबसे अंत में तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा।"},
  {"q":"5 मार्च 1931 का 'गांधी-इरविन समझौता' (दिल्ली समझौता) किस संदर्भ में हुआ था?","options":["तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत","प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी","ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति","सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी"],"correct":3,"explanation":"तेज बहादुर सप्रू व एम.आर. जयकर के प्रयासों से 5 मार्च 1931 को गांधी-इरविन समझौता हुआ। सरोजिनी नायडू ने इसे 'दो महात्माओं का मिलन' कहा; इसने नमक बनाने व शांतिपूर्ण धरने की अनुमति दी।"},
  {"q":"[PSC/CDS युग्म पहचान — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. विजयी विश्व तिरंगा प्यारा : लाला लाजपत राय\n2. तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा : सुभाष चंद्र बोस\n3. मेरे शरीर पर पड़ी एक-एक लाठी... : भगत सिंह (रचयिता: हसरत मोहानी)\n4. इंकलाब जिंदाबाद : जवाहरलाल नेहरू","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: नेताजी सुभाष चंद्र बोस ने दक्षिण-पूर्व एशिया में आजाद हिंद फौज के सैनिकों को प्रेरित करने हेतु यह आह्वान किया। (अन्य सही युग्म: विजयी विश्व तिरंगा प्यारा→श्यामलाल गुप्त 'पार्षद', मेरे शरीर पर पड़ी एक-एक लाठी...→लाला लाजपत राय, इंकलाब जिंदाबाद→भगत सिंह (रचयिता: हसरत मोहानी))।"}
]);
